mapper.select:
SELECT post_id AS id, user_id AS userId, post_title AS title, created_at AS createdAt, view_count AS viewCount FROM post WHERE deleted_at IS NULL
AND MATCH(post_title, post_content) AGAINST(CONCAT('+', #{searchKeyword}, '*') IN BOOLEAN MODE)
AND user_id = #{searchUser}
ORDER BY post_id DESC
LIMIT #{pageSize} OFFSET #{offset}

SELECT count(*) FROM post WHERE deleted_at IS NULL
AND MATCH(post_title, post_content) AGAINST(CONCAT('+', #{searchKeyword}, '*') IN BOOLEAN MODE)
AND user_id = #{searchUser}

mapper.update:
UPDATE post
SET post_title = #{post.title}, post_content = #{post.content}
WHERE post_id = #{postId}

UPDATE post
SET updated_at = updated_at, deleted_at = NOW()
WHERE post_id = #{postId}

mapper.select:
SELECT EXISTS(
    SELECT 1
    FROM post
    WHERE post_id = #{postId}
    AND deleted_at IS NULL
)
